type OutBufFuture struct {
	c    *Client
	call *rt.Call
	id   uint32
	dst  []byte
}

// out_buf(key, out buf, cap)
//
// Results: (buf, error).
//
// p_buf is the output storage, its length is the capacity sent to the server, and the result is p_buf[:n]. The slices must stay untouched until Wait returns.
func (c *Client) OutBuf(p_key uint8, p_buf []byte) ([]byte, error) {
	f, err := c.OutBufAsync(p_key, p_buf)
	if err != nil {
		return nil, err
	}
	return f.Wait()
}

func (c *Client) OutBufAsync(p_key uint8, p_buf []byte) (OutBufFuture, error) {
	if len(p_buf) > 100 { // buf: bytes<=100
		return OutBufFuture{}, rt.ErrInvalidArg
	}
	// G1: key u8 @0, buf.cap u32 @4; no variable group.
	// RESP_BOUND = G2pad 8 + VarSlack + cap of buf (4.6.3), in 64 bits.
	e, err := c.c.BeginRequest(hqqOpOutBuf, 8, 8+rt.VarSlack+int64(len(p_buf)))
	if err != nil {
		return OutBufFuture{}, err
	}
	body := e.Body()
	body[0] = p_key
	clear(body[1:4])
	hqqLE.PutUint32(body[4:], uint32(len(p_buf)))
	call, err := c.c.Submit(e)
	if err != nil {
		return OutBufFuture{}, err
	}
	return OutBufFuture{c, call, call.ID(), p_buf}, nil
}

func (f OutBufFuture) Wait() ([]byte, error) {
	if f.c == nil {
		return nil, rt.ErrFutureUsed
	}
	d, err := f.c.c.Wait(f.call, f.id)
	if err != nil {
		return nil, err
	}
	defer d.Release()
	b := d.Body
	// G2: ret u32 @0 (size 4); V2: buf from 8.
	if len(b) < 4 || d.Fail || d.Detail {
		return nil, d.Malformed()
	}
	ret := hqqLE.Uint32(b[0:])
	n, end, err := rt.GetBytesInto(f.dst, b, 8)
	if err != nil || end != len(b) || uint64(n) != uint64(ret) {
		return nil, d.Malformed()
	}
	return f.dst[:n], nil
}

type OutArrFuture struct {
	c    *Client
	call *rt.Call
	id   uint32
	dst  []int32
}

// out_arr(out items, cap, out n)
//
// Results: (items, error).
//
// p_items is the output storage, its length is the capacity sent to the server, and the result is p_items[:n]. The slices must stay untouched until Wait returns.
func (c *Client) OutArr(p_items []int32) ([]int32, error) {
	f, err := c.OutArrAsync(p_items)
	if err != nil {
		return nil, err
	}
	return f.Wait()
}

func (c *Client) OutArrAsync(p_items []int32) (OutArrFuture, error) {
	if len(p_items) > 10 { // items: i32[]<=10
		return OutArrFuture{}, rt.ErrInvalidArg
	}
	// G1: items.cap u32 @0; no variable group.
	// RESP_BOUND = G2pad 0 + VarSlack + cap of items (4.6.3), in 64 bits.
	e, err := c.c.BeginRequest(hqqOpOutArr, 4, rt.VarSlack+int64(len(p_items))*4)
	if err != nil {
		return OutArrFuture{}, err
	}
	body := e.Body()
	hqqLE.PutUint32(body[0:], uint32(len(p_items)))
	call, err := c.c.Submit(e)
	if err != nil {
		return OutArrFuture{}, err
	}
	return OutArrFuture{c, call, call.ID(), p_items}, nil
}

func (f OutArrFuture) Wait() ([]int32, error) {
	if f.c == nil {
		return nil, rt.ErrFutureUsed
	}
	d, err := f.c.c.Wait(f.call, f.id)
	if err != nil {
		return nil, err
	}
	defer d.Release()
	b := d.Body
	// G2: none; V2: items from 0.
	if d.Fail || d.Detail {
		return nil, d.Malformed()
	}
	cnt, off, err := rt.GetCount(b, 0, len(f.dst), 4) // i32[]<=10, minsize(i32) = 4
	if err != nil {
		return nil, d.Malformed()
	}
	out := f.dst[:0]
	for i := uint32(0); i < cnt; i++ {
		var v int32
		off = rt.Align(off, 4)
		if off+4 > len(b) {
			return nil, d.Malformed()
		}
		v = int32(hqqLE.Uint32(b[off:]))
		off += 4
		out = append(out, v)
	}
	if off != len(b) {
		return nil, d.Malformed()
	}
	return out, nil
}

type OutPtsFuture struct {
	c    *Client
	call *rt.Call
	id   uint32
	dst  []Pt
}

// out_pts(out pts, cap, out m, flag)
//
// Results: (pts, error).
//
// p_pts is the output storage, its length is the capacity sent to the server, and the result is p_pts[:n]. The slices must stay untouched until Wait returns.
func (c *Client) OutPts(p_pts []Pt, p_flag bool) ([]Pt, error) {
	f, err := c.OutPtsAsync(p_pts, p_flag)
	if err != nil {
		return nil, err
	}
	return f.Wait()
}

func (c *Client) OutPtsAsync(p_pts []Pt, p_flag bool) (OutPtsFuture, error) {
	// G1: pts.cap u32 @0, flag bool @4; no variable group.
	// RESP_BOUND = G2pad 0 + VarSlack + cap of pts (4.6.3), in 64 bits.
	e, err := c.c.BeginRequest(hqqOpOutPts, 5, rt.VarSlack+int64(len(p_pts))*12)
	if err != nil {
		return OutPtsFuture{}, err
	}
	body := e.Body()
	hqqLE.PutUint32(body[0:], uint32(len(p_pts)))
	body[4] = 0
	if p_flag {
		body[4] = 1
	}
	call, err := c.c.Submit(e)
	if err != nil {
		return OutPtsFuture{}, err
	}
	return OutPtsFuture{c, call, call.ID(), p_pts}, nil
}

func (f OutPtsFuture) Wait() ([]Pt, error) {
	if f.c == nil {
		return nil, rt.ErrFutureUsed
	}
	d, err := f.c.c.Wait(f.call, f.id)
	if err != nil {
		return nil, err
	}
	defer d.Release()
	b := d.Body
	// G2: none; V2: pts from 0.
	if d.Fail || d.Detail {
		return nil, d.Malformed()
	}
	cnt, off, err := rt.GetCount(b, 0, len(f.dst), 12) // Pt[], minsize(Pt) = 12
	if err != nil {
		return nil, d.Malformed()
	}
	out := f.dst[:0]
	for i := uint32(0); i < cnt; i++ {
		var v Pt
		off = rt.Align(off, 4)
		if off+12 > len(b) {
			return nil, d.Malformed()
		}
		v.X = int32(hqqLE.Uint32(b[off:]))
		v.Y = int32(hqqLE.Uint32(b[off+4:]))
		v.W = math.Float32frombits(hqqLE.Uint32(b[off+8:]))
		off += 12
		out = append(out, v)
	}
	if off != len(b) {
		return nil, d.Malformed()
	}
	return out, nil
}

type TwoBufsFuture struct {
	c     *Client
	call  *rt.Call
	id    uint32
	dst_a []byte
	dst_b []byte
}

// two_bufs(out a, acap, out b, bcap, s)
//
// Results: (ret, a, b, error).
//
// p_a is the output storage, its length is the capacity sent to the server, and the result is p_a[:n]; p_b is the output storage, its length is the capacity sent to the server, and the result is p_b[:n]. The slices must stay untouched until Wait returns.
func (c *Client) TwoBufs(p_a, p_b []byte, p_s string) (int32, []byte, []byte, error) {
	f, err := c.TwoBufsAsync(p_a, p_b, p_s)
	if err != nil {
		return 0, nil, nil, err
	}
	return f.Wait()
}

func (c *Client) TwoBufsAsync(p_a, p_b []byte, p_s string) (TwoBufsFuture, error) {
	if len(p_b) > 8 { // b: bytes<=8
		return TwoBufsFuture{}, rt.ErrInvalidArg
	}
	if err := rt.CheckStr(p_s, 0); err != nil {
		return TwoBufsFuture{}, err
	}
	// G1: a.cap u32 @0, b.cap u32 @4; V1: s from 8.
	// RESP_BOUND = G2pad 8 + VarSlack + cap of a + VarSlack + cap of b (4.6.3), in 64 bits.
	e, err := c.c.BeginRequest(hqqOpTwoBufs, 8+rt.StrWire(len(p_s)), 8+rt.VarSlack+int64(len(p_a))+rt.VarSlack+int64(len(p_b)))
	if err != nil {
		return TwoBufsFuture{}, err
	}
	body := e.Body()
	hqqLE.PutUint32(body[0:], uint32(len(p_a)))
	hqqLE.PutUint32(body[4:], uint32(len(p_b)))
	rt.PutStr(body, 8, p_s)
	call, err := c.c.Submit(e)
	if err != nil {
		return TwoBufsFuture{}, err
	}
	return TwoBufsFuture{c, call, call.ID(), p_a, p_b}, nil
}

func (f TwoBufsFuture) Wait() (int32, []byte, []byte, error) {
	if f.c == nil {
		return 0, nil, nil, rt.ErrFutureUsed
	}
	d, err := f.c.c.Wait(f.call, f.id)
	if err != nil {
		return 0, nil, nil, err
	}
	defer d.Release()
	b := d.Body
	// G2: ret i32 @0 (size 4); V2: a, b from 8.
	if len(b) < 4 || d.Fail || d.Detail {
		return 0, nil, nil, d.Malformed()
	}
	n, off, err := rt.GetBytesInto(f.dst_a, b, 8)
	if err != nil {
		return 0, nil, nil, d.Malformed()
	}
	n1, end, err := rt.GetBytesInto(f.dst_b, b, off)
	if err != nil || end != len(b) {
		return 0, nil, nil, d.Malformed()
	}
	return int32(hqqLE.Uint32(b[0:])), f.dst_a[:n], f.dst_b[:n1], nil
}

type OutFixedFuture struct {
	c    *Client
	call *rt.Call
	id   uint32
}

// out_fixed(out key, out m, out p, out box, out ok)
//
// Results: (ret, key, m, p, box, ok, error).
func (c *Client) OutFixed() (uint8, [32]uint8, [3]int16, Pt, Box, bool, error) {
	f, err := c.OutFixedAsync()
	if err != nil {
		return 0, [32]uint8{}, [3]int16{}, Pt{}, Box{}, false, err
	}
	return f.Wait()
}

func (c *Client) OutFixedAsync() (OutFixedFuture, error) {
	// G1: none; no variable group.
	// RESP_BOUND = G2pad 113 (4.6.3), in 64 bits.
	e, err := c.c.BeginRequest(hqqOpOutFixed, 0, 113)
	if err != nil {
		return OutFixedFuture{}, err
	}
	call, err := c.c.Submit(e)
	if err != nil {
		return OutFixedFuture{}, err
	}
	return OutFixedFuture{c, call, call.ID()}, nil
}

func (f OutFixedFuture) Wait() (uint8, [32]uint8, [3]int16, Pt, Box, bool, error) {
	if f.c == nil {
		return 0, [32]uint8{}, [3]int16{}, Pt{}, Box{}, false, rt.ErrFutureUsed
	}
	d, err := f.c.c.Wait(f.call, f.id)
	if err != nil {
		return 0, [32]uint8{}, [3]int16{}, Pt{}, Box{}, false, err
	}
	defer d.Release()
	b := d.Body
	// G2: ret u8 @0, key u8[32] @1, m i16[3] @34, p Pt @40, box Box @56, ok bool @112 (size 113).
	if len(b) != 113 || b[112] > 1 || d.Fail {
		return 0, [32]uint8{}, [3]int16{}, Pt{}, Box{}, false, d.Malformed()
	}
	var r [32]uint8
	copy(r[:], b[1:33])
	var r1 [3]int16
	for i := range r1 {
		r1[i] = int16(hqqLE.Uint16(b[34+i*2:]))
	}
	var r2 Pt
	r2.X = int32(hqqLE.Uint32(b[40:]))
	r2.Y = int32(hqqLE.Uint32(b[44:]))
	r2.W = math.Float32frombits(hqqLE.Uint32(b[48:]))
	var r3 Box
	for i1 := range r3.Rows {
		r3.Rows[i1] = int16(hqqLE.Uint16(b[56+i1*2:]))
	}
	for i2 := range r3.Pts {
		r3.Pts[i2].X = int32(hqqLE.Uint32(b[64+i2*12:]))
		r3.Pts[i2].Y = int32(hqqLE.Uint32(b[64+i2*12+4:]))
		r3.Pts[i2].W = math.Float32frombits(hqqLE.Uint32(b[64+i2*12+8:]))
	}
	if b[88] > 1 {
		return 0, [32]uint8{}, [3]int16{}, Pt{}, Box{}, false, d.Malformed()
	}
	r3.Flag = b[88] == 1
	r3.Tag = hqqLE.Uint64(b[96:])
	copy(r3.Key[:], b[104:108])
	return b[0], r, r1, r2, r3, b[112] == 1, nil
}

type OutBorrowedFuture struct {
	c    *Client
	call *rt.Call
	id   uint32
}

// out_borrowed(out msg, out data, out dlen, out items, out ilen)
//
// Results: (ret, msg, data, items, error).
func (c *Client) OutBorrowed() (int32, string, []byte, []int32, error) {
	f, err := c.OutBorrowedAsync()
	if err != nil {
		return 0, "", nil, nil, err
	}
	return f.Wait()
}

func (c *Client) OutBorrowedAsync() (OutBorrowedFuture, error) {
	// G1: none; no variable group.
	// RESP_BOUND = G2pad 8 + msg 76 + data 267 + items 75 (4.6.3), in 64 bits.
	e, err := c.c.BeginRequest(hqqOpOutBorrowed, 0, 426)
	if err != nil {
		return OutBorrowedFuture{}, err
	}
	call, err := c.c.Submit(e)
	if err != nil {
		return OutBorrowedFuture{}, err
	}
	return OutBorrowedFuture{c, call, call.ID()}, nil
}

func (f OutBorrowedFuture) Wait() (int32, string, []byte, []int32, error) {
	if f.c == nil {
		return 0, "", nil, nil, rt.ErrFutureUsed
	}
	d, err := f.c.c.Wait(f.call, f.id)
	if err != nil {
		return 0, "", nil, nil, err
	}
	defer d.Release()
	b := d.Body
	// G2: ret i32 @0 (size 4); V2: msg, data, items from 8.
	if len(b) < 4 || d.Fail || d.Detail {
		return 0, "", nil, nil, d.Malformed()
	}
	r, off, err := rt.GetStr(b, 8, 64)
	if err != nil {
		return 0, "", nil, nil, d.Malformed()
	}
	cnt, off, err := rt.GetCount(b, off, 256, 1)
	if err != nil {
		return 0, "", nil, nil, d.Malformed()
	}
	r1 := append([]byte(nil), b[off:off+int(cnt)]...)
	off += int(cnt)
	cnt1, off, err := rt.GetCount(b, off, 16, 4) // i32[]<=16, minsize(i32) = 4
	if err != nil {
		return 0, "", nil, nil, d.Malformed()
	}
	out := make([]int32, 0, cnt1)
	for i := uint32(0); i < cnt1; i++ {
		var v int32
		off = rt.Align(off, 4)
		if off+4 > len(b) {
			return 0, "", nil, nil, d.Malformed()
		}
		v = int32(hqqLE.Uint32(b[off:]))
		off += 4
		out = append(out, v)
	}
	if off != len(b) {
		return 0, "", nil, nil, d.Malformed()
	}
	return int32(hqqLE.Uint32(b[0:])), r, r1, out, nil
}

type PrepFuture struct {
	c    *Client
	call *rt.Call
	id   uint32
}

// prep(db, sql, nbyte, out stmt, out tail)
//
// Results: (stmt, tail, error).
//
// @error(status, ok(0)): any other return value is a *rt.LibError carrying it as Code; Detail is the text of db_errmsg.
func (c *Client) Prep(p_db Db, p_sql string) (Stmt, uint32, error) {
	f, err := c.PrepAsync(p_db, p_sql)
	if err != nil {
		return Stmt{}, 0, err
	}
	return f.Wait()
}

func (c *Client) PrepAsync(p_db Db, p_sql string) (PrepFuture, error) {
	if err := c.c.CheckHandle(p_db.Handle, false); err != nil {
		return PrepFuture{}, err
	}
	if err := rt.CheckStr(p_sql, 0); err != nil {
		return PrepFuture{}, err
	}
	// G1: db u32 @0; V1: sql from 8.
	// RESP_BOUND = max(G2pad 16, G2pad + DETAIL_RESERVE) (4.6.3), in 64 bits.
	e, err := c.c.BeginRequest(hqqOpPrep, 8+rt.StrWire(len(p_sql)), 16+rt.DetailReserve)
	if err != nil {
		return PrepFuture{}, err
	}
	body := e.Body()
	hqqLE.PutUint32(body[0:], p_db.ID())
	clear(body[4:8])
	rt.PutStr(body, 8, p_sql)
	call, err := c.c.Submit(e)
	if err != nil {
		return PrepFuture{}, err
	}
	return PrepFuture{c, call, call.ID()}, nil
}

