	// RESP_BOUND = max(G2pad 16 + s 28, G2pad + DETAIL_RESERVE) (4.6.3), in 64 bits.
	e, err := c.c.BeginRequest(hqqOpStep, 16, 16+rt.DetailReserve)
	if err != nil {
		return StepFuture{}, err
	}
	body := e.Body()
	hqqLE.PutUint32(body[0:], p_stmt.ID())
	clear(body[4:8])
	hqqLE.PutUint64(body[8:], uint64(p_x))
	call, err := c.c.Submit(e)
	if err != nil {
		return StepFuture{}, err
	}
	return StepFuture{c, call, call.ID()}, nil
