type GetValFuture struct {
	c    *Client
	call *rt.Call
	id   uint32
}

// get_val(db)
//
// Results: (ret, error).
func (c *Client) GetVal(p_db Db) (Val, error) {
	f, err := c.GetValAsync(p_db)
	if err != nil {
		return Val{}, err
	}
	return f.Wait()
}

func (c *Client) GetValAsync(p_db Db) (GetValFuture, error) {
	if err := c.c.CheckHandle(p_db.Handle, false); err != nil {
		return GetValFuture{}, err
	}
	// G1: db u32 @0; no variable group.
	// RESP_BOUND = G2pad 0 + ret 4096 (4.6.3), in 64 bits.
	e, err := c.c.BeginRequest(hqqOpGetVal, 4, 4096)
	if err != nil {
		return GetValFuture{}, err
	}
	body := e.Body()
	hqqLE.PutUint32(body[0:], p_db.ID())
	call, err := c.c.Submit(e)
	if err != nil {
		return GetValFuture{}, err
	}
	return GetValFuture{c, call, call.ID()}, nil
}

func (f GetValFuture) Wait() (Val, error) {
	if f.c == nil {
		return Val{}, rt.ErrFutureUsed
	}
	d, err := f.c.c.Wait(f.call, f.id)
	if err != nil {
		return Val{}, err
	}
	defer d.Release()
	b := d.Body
	// G2: none; V2: ret from 0.
	if d.Fail || d.Detail {
		return Val{}, d.Malformed()
	}
	off := 0
	var r Val
	off = rt.Align(off, 4)
	if off+4 > len(b) {
		return Val{}, d.Malformed()
	}
	r.Tag = ValTag(hqqLE.Uint32(b[off:]))
	off += 4
	switch r.Tag {
	case ValI:
		off = rt.Align(off, 8)
		if off+8 > len(b) {
			return Val{}, d.Malformed()
		}
		r.I = int64(hqqLE.Uint64(b[off:]))
		off += 8
	case ValF:
		off = rt.Align(off, 8)
		if off+8 > len(b) {
			return Val{}, d.Malformed()
		}
		r.F = math.Float64frombits(hqqLE.Uint64(b[off:]))
		off += 8
	case ValS:
		if r.S, off, err = rt.GetStr(b, off, 0); err != nil {
			return Val{}, d.Malformed()
		}
	case ValB:
		var cnt uint32
		cnt, off, err = rt.GetCount(b, off, 64, 1)
		if err != nil {
			return Val{}, d.Malformed()
		}
		r1 := append([]byte(nil), b[off:off+int(cnt)]...)
		off += int(cnt)
		r.B = r1
	case ValN:
	case ValR:
		off = rt.Align(off, 8)
		if off+8 > len(b) {
			return Val{}, d.Malformed()
		}
		r.R.Id = hqqLE.Uint64(b[off:])
		off += 8
		if r.R.Name, off, err = rt.GetStr(b, off, 32); err != nil {
			return Val{}, d.Malformed()
		}
		var cnt1 uint32
		cnt1, off, err = rt.GetCount(b, off, 8, 4) // i32[]<=8, minsize(i32) = 4
		if err != nil {
			return Val{}, d.Malformed()
		}
		out := make([]int32, 0, cnt1)
		for i := uint32(0); i < cnt1; i++ {
			var v int32
			off = rt.Align(off, 4)
			if off+4 > len(b) {
				return Val{}, d.Malformed()
			}
			v = int32(hqqLE.Uint32(b[off:]))
			off += 4
			out = append(out, v)
		}
		r.R.Tags = out
		off = rt.Align(off, 4)
		if off+12 > len(b) {
			return Val{}, d.Malformed()
		}
		r.R.Inner.A = b[off]
		r.R.Inner.B = hqqLE.Uint32(b[off+4:])
		r.R.Inner.C = hqqLE.Uint16(b[off+8:])
		if b[off+10] > 1 {
			return Val{}, d.Malformed()
		}
		r.R.Inner.Ok = b[off+10] == 1
		off += 12
	case ValP:
		off = rt.Align(off, 4)
		if off+12 > len(b) {
			return Val{}, d.Malformed()
		}
		r.P.X = int32(hqqLE.Uint32(b[off:]))
		r.P.Y = int32(hqqLE.Uint32(b[off+4:]))
		r.P.W = math.Float32frombits(hqqLE.Uint32(b[off+8:]))
		off += 12
	case ValFlag:
		if off+1 > len(b) {
			return Val{}, d.Malformed()
		}
		if b[off] > 1 {
			return Val{}, d.Malformed()
		}
		r.Flag = b[off] == 1
		off += 1
	default:
		return Val{}, d.Malformed()
	}
	if off != len(b) {
		return Val{}, d.Malformed()
	}
	return r, nil
}

